    const f = vi.fn<typeof fetch>().mockImplementation(async () => new Response("", { status: 429, headers: { "retry-after": "30" } }));
    await expect(make(f, { maxRateLimitWaitMs: 70_000 })(req)).rejects.toMatchObject({ kind: "rate_limit" });
