// Evaluation metrics (CLAUDE.md "Evaluation"). Pure functions: no database, no network, no env.
// Used by scripts/eval.ts AND the /eval page, so the two can never disagree.
// Scores against the hand labels only, never against corrections.
import { CATEGORIES, type Category } from "./categories";

/** One reply that has a result, with my label beside it. */
export type EvalRow = {
  id: string;
  body: string;
  /** My label (v0 category from labels.json). */
  label: Category;
  /** What the model alone would have shown: its category + rank mapped to v0, before any code rule. */
  model: Category;
  /** What the app shows: after the code rules. */
  final: Category;
  needsReview: boolean;
  reasoning: string | null;
  overrideReasons: string[];
  reviewReasons: string[];
};

export type CategoryScore = {
  category: Category;
  /** Replies my labels put in this category. */
  support: number;
  /** Replies the system put in this category. */
  predicted: number;
  truePositives: number;
  /** null when nothing was predicted (precision) or nothing was labelled (recall). */
  precision: number | null;
  recall: number | null;
};

export type SystemScore = {
  perCategory: CategoryScore[];
  /** matrix[label][predicted] = number of replies. */
  confusion: Record<Category, Record<Category, number>>;
  accuracy: number | null;
  /** Marked paid, but my label says otherwise. The costliest mistake. */
  falsePaid: { count: number; ids: string[] };
  /** Labelled paid but not marked paid. Safe direction: a person checks it. */
  missedPaid: { count: number; ids: string[] };
};

export type Mismatch = EvalRow;

export type Metrics = {
  coverage: { scored: number; total: number; failed: number; missing: number };
  /** The model's answer alone, before the code rules. */
  model: SystemScore;
  /** What the app shows, after the code rules. */
  final: SystemScore;
  /** Share of scored replies sent to a person. */
  reviewRate: number | null;
  reviewed: number;
  /** Replies the final answer got wrong. */
  wrong: number;
  /** Of those, how many were NOT in the review queue: mistakes nobody would see. */
  wrongNotReviewed: { count: number; ids: string[] };
  /** Replies the code rules changed to a different category, and how many of those became correct / incorrect. */
  rulesChanged: { count: number; fixed: string[]; broke: string[] };
  /** Every reply whose final category differs from my label. */
  mismatches: Mismatch[];
  /** Replies where the raw model answer differed from my label, but the final answer matched (rules caught them). */
  caughtByRules: string[];
};

const ratio = (a: number, b: number) => (b === 0 ? null : a / b);

function emptyMatrix(): Record<Category, Record<Category, number>> {
  const m = {} as Record<Category, Record<Category, number>>;
  for (const l of CATEGORIES) {
    m[l] = {} as Record<Category, number>;
    for (const p of CATEGORIES) m[l][p] = 0;
  }
  return m;
}

function scoreSystem(rows: EvalRow[], pick: (r: EvalRow) => Category): SystemScore {
  const confusion = emptyMatrix();
  for (const r of rows) confusion[r.label][pick(r)]++;

  const perCategory = CATEGORIES.map((category): CategoryScore => {
    const truePositives = confusion[category][category];
    const support = CATEGORIES.reduce((n, p) => n + confusion[category][p], 0);
    const predicted = CATEGORIES.reduce((n, l) => n + confusion[l][category], 0);
    return { category, support, predicted, truePositives, precision: ratio(truePositives, predicted), recall: ratio(truePositives, support) };
  });

  const falsePaidIds = rows.filter((r) => pick(r) === "paid" && r.label !== "paid").map((r) => r.id);
  const missedPaidIds = rows.filter((r) => r.label === "paid" && pick(r) !== "paid").map((r) => r.id);
  const correct = rows.filter((r) => pick(r) === r.label).length;
  return {
    perCategory,
    confusion,
    accuracy: ratio(correct, rows.length),
    falsePaid: { count: falsePaidIds.length, ids: falsePaidIds },
    missedPaid: { count: missedPaidIds.length, ids: missedPaidIds },
  };
}

/**
 * @param rows   replies that have a current (successful) result
 * @param total  how many replies the set should have (40, or 12 held-out)
 * @param failed how many replies have only failed attempts
 */
export function computeMetrics(rows: EvalRow[], total: number, failed = 0): Metrics {
  const mismatches = rows.filter((r) => r.final !== r.label);
  const reviewed = rows.filter((r) => r.needsReview).length;
  const wrongNotReviewed = mismatches.filter((r) => !r.needsReview).map((r) => r.id);
  const changed = rows.filter((r) => r.model !== r.final);

  return {
    coverage: { scored: rows.length, total, failed, missing: Math.max(0, total - rows.length - failed) },
    model: scoreSystem(rows, (r) => r.model),
    final: scoreSystem(rows, (r) => r.final),
    reviewRate: ratio(reviewed, rows.length),
    reviewed,
    wrong: mismatches.length,
    wrongNotReviewed: { count: wrongNotReviewed.length, ids: wrongNotReviewed },
    rulesChanged: {
      count: changed.length,
      fixed: changed.filter((r) => r.final === r.label).map((r) => r.id),
      broke: changed.filter((r) => r.model === r.label).map((r) => r.id),
    },
    mismatches,
    caughtByRules: rows.filter((r) => r.model !== r.label && r.final === r.label).map((r) => r.id),
  };
}

export const pct = (x: number | null) => (x === null ? "n/a" : `${(x * 100).toFixed(0)}%`);

import { describe, expect, it } from "vitest";
import type { Category } from "../src/lib/categories";
import { computeMetrics, pct, type EvalRow } from "../src/lib/metrics";

const row = (id: string, label: Category, model: Category, final: Category = model, needsReview = false): EvalRow => ({
  id, body: `body ${id}`, label, model, final, needsReview, reasoning: null, overrideReasons: [], reviewReasons: [],
});
const score = (m: ReturnType<typeof computeMetrics>["final"], c: Category) => m.perCategory.find((p) => p.category === c)!;

describe("precision and recall", () => {
  // paid: 3 labelled, 2 found, 1 false paid (a dispute marked paid).
  const rows = [
    row("1", "paid", "paid"),
    row("2", "paid", "paid"),
    row("3", "paid", "needs_human"),
    row("4", "dispute", "paid"),
    row("5", "dispute", "dispute"),
    row("6", "needs_human", "needs_human"),
  ];
  const m = computeMetrics(rows, 6);

  it("computes per-category counts, precision and recall", () => {
    expect(score(m.final, "paid")).toMatchObject({ support: 3, predicted: 3, truePositives: 2, precision: 2 / 3, recall: 2 / 3 });
    expect(score(m.final, "dispute")).toMatchObject({ support: 2, predicted: 1, precision: 1, recall: 0.5 });
    expect(score(m.final, "needs_human")).toMatchObject({ support: 1, predicted: 2, precision: 0.5, recall: 1 });
  });
  it("is null, not 0 or NaN, when a category has no predictions or no examples", () => {
    expect(score(m.final, "resend_invoice")).toMatchObject({ support: 0, predicted: 0, precision: null, recall: null });
    expect(pct(null)).toBe("n/a");
  });
  it("builds the confusion matrix as matrix[label][predicted]", () => {
    expect(m.final.confusion.paid.paid).toBe(2);
    expect(m.final.confusion.paid.needs_human).toBe(1);
    expect(m.final.confusion.dispute.paid).toBe(1);
  });
  it("counts accuracy", () => expect(m.final.accuracy).toBe(4 / 6));
});

describe("the headline: false paid", () => {
  it("counts a reply marked paid that my label says isn't, and lists it", () => {
    const m = computeMetrics([row("1", "paid", "paid"), row("2", "dispute", "paid"), row("3", "needs_human", "paid")], 3);
    expect(m.final.falsePaid).toEqual({ count: 2, ids: ["2", "3"] });
  });
  it("is zero when no non-paid reply is marked paid", () => {
    const m = computeMetrics([row("1", "paid", "paid"), row("2", "dispute", "needs_human")], 2);
    expect(m.final.falsePaid.count).toBe(0);
  });
  it("counts a missed paid separately (the safe direction)", () => {
    const m = computeMetrics([row("1", "paid", "needs_human")], 1);
    expect(m.final.falsePaid.count).toBe(0);
    expect(m.final.missedPaid).toEqual({ count: 1, ids: ["1"] });
  });
});

describe("model alone vs after the code rules", () => {
  // #1: the model said paid wrongly and the rules fixed it. #2: the rules wrongly changed a right answer.
  const rows = [
    row("1", "needs_human", "paid", "needs_human", true),
    row("2", "dispute", "dispute", "needs_human", true),
    row("3", "paid", "paid", "paid"),
  ];
  const m = computeMetrics(rows, 3);
  it("scores both, so the gap shows what the rules caught", () => {
    expect(m.model.falsePaid.count).toBe(1);
    expect(m.final.falsePaid.count).toBe(0);
    expect(m.caughtByRules).toEqual(["1"]);
  });
  it("reports how many rule changes fixed or broke an answer", () => {
    expect(m.rulesChanged).toEqual({ count: 2, fixed: ["1"], broke: ["2"] });
  });
});

describe("review rate and unseen mistakes", () => {
  const rows = [
    row("1", "paid", "paid", "paid", false),
    row("2", "dispute", "needs_human", "needs_human", true), // wrong, but a person will see it
    row("3", "promise_to_pay", "dispute", "dispute", false), // wrong and nobody will see it
    row("4", "out_of_office", "out_of_office", "out_of_office", false),
  ];
  const m = computeMetrics(rows, 4);
  it("review rate is the share sent to a person", () => {
    expect(m.reviewed).toBe(1);
    expect(m.reviewRate).toBe(0.25);
  });
  it("lists the wrong answers that were not in the review queue", () => {
    expect(m.wrong).toBe(2);
    expect(m.wrongNotReviewed).toEqual({ count: 1, ids: ["3"] });
  });
  it("lists every mismatch with its row", () => {
    expect(m.mismatches.map((r) => r.id)).toEqual(["2", "3"]);
  });
});

describe("coverage", () => {
  it("shows a partial run as partial", () => {
    const m = computeMetrics([row("1", "paid", "paid")], 40, 2);
    expect(m.coverage).toEqual({ scored: 1, total: 40, failed: 2, missing: 37 });
  });
  it("handles an empty run", () => {
    const m = computeMetrics([], 40);
    expect(m.reviewRate).toBeNull();
    expect(m.final.accuracy).toBeNull();
    expect(m.coverage.missing).toBe(40);
  });
});

import { and, eq } from "drizzle-orm";
import heldoutLabels from "../../data/heldout-labels.json";
import datasetLabels from "../../data/labels.json";
import { CATEGORIES, toV0, type Category } from "../lib/categories";
import { computeMetrics, type EvalRow, type Metrics } from "../lib/metrics";
import { getDb } from "./client";
import { currentResultRows, repliesBySource, type ActiveRun } from "./queries";
import { classifications, replies } from "./schema";

// The evaluation, built from stored results and MY labels (data/*labels.json). It never reads the
// corrections table: a correction made in a demo must not change precision or recall.
// Shared by scripts/eval.ts and the /eval page.

export type EvalSet = "dataset" | "heldout";

type LabelRow = { id: string; v0_category: string };
const LABEL_FILES: Record<EvalSet, LabelRow[]> = { dataset: datasetLabels, heldout: heldoutLabels };

export type EvalResult = {
  set: EvalSet;
  model: string;
  promptVersion: string;
  generatedAt: string;
  /** Everything spent on this model + prompt version for this set, including failed and retried calls. */
  tokens: { prompt: number; completion: number; total: number };
  metrics: Metrics;
};

export async function buildEval(run: ActiveRun, set: EvalSet = "dataset"): Promise<EvalResult> {
  const labels = new Map<string, Category>();
  for (const l of LABEL_FILES[set]) {
    if (!(CATEGORIES as readonly string[]).includes(l.v0_category)) throw new Error(`Bad label for ${l.id}: ${l.v0_category}`);
    labels.set(l.id, l.v0_category as Category);
  }

  const setReplies = await repliesBySource(set);
  const bodies = new Map(setReplies.map((r) => [r.id, r.body]));
  const current = (await currentResultRows(run)).filter((r) => bodies.has(r.replyId));

  const rows: EvalRow[] = current.map((c) => {
    const label = labels.get(c.replyId);
    if (!label) throw new Error(`No label for reply ${c.replyId}`);
    return {
      id: c.replyId,
      body: bodies.get(c.replyId)!,
      label,
      // The model alone, before any code rule: its category + rank mapped to v0 (an invalid pair counts as needs_human).
      model: c.modelCategory && c.modelRank !== null ? (toV0(c.modelCategory, c.modelRank) ?? "needs_human") : "needs_human",
      final: c.finalCategory,
      needsReview: c.needsReview,
      reasoning: c.reasoning,
      overrideReasons: c.overrideReasons,
      reviewReasons: c.reviewReasons,
    };
  });

  // All rows for this run in this set: failed-only replies for coverage, and total tokens spent.
  const all = await getDb()
    .select({ replyId: classifications.replyId, error: classifications.error, p: classifications.promptTokens, c: classifications.completionTokens })
    .from(classifications)
    .innerJoin(replies, eq(replies.id, classifications.replyId))
    .where(and(eq(classifications.model, run.model), eq(classifications.promptVersion, run.promptVersion), eq(replies.source, set)));
  const scored = new Set(rows.map((r) => r.id));
  const failedOnly = new Set(all.filter((r) => r.error && !scored.has(r.replyId)).map((r) => r.replyId));
  const prompt = all.reduce((n, r) => n + (r.p ?? 0), 0);
  const completion = all.reduce((n, r) => n + (r.c ?? 0), 0);

  return {
    set,
    model: run.model,
    promptVersion: run.promptVersion,
    generatedAt: new Date().toISOString(),
    tokens: { prompt, completion, total: prompt + completion },
    metrics: computeMetrics(rows, labels.size, failedOnly.size),
  };
}

/** results-v1-gpt-oss-120b.json, or heldout-results-… for the held-out set. */
export function resultsFileName(r: Pick<EvalResult, "set" | "model" | "promptVersion">): string {
  const model = r.model.split("/").pop();
  return `${r.set === "heldout" ? "heldout-results" : "results"}-${r.promptVersion}-${model}.json`;
}

