// Drives headless Chrome over the DevTools protocol: type a reply, click Submit three times in 160 ms,
// record the button's state after each click, then wait for the redirect and report where it landed.
const list = await (await fetch("http://127.0.0.1:9333/json/list")).json();
const page = list.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const waiting = new Map();
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && waiting.has(d.id)) {
    waiting.get(d.id)(d);
    waiting.delete(d.id);
  }
};
const send = (method, params = {}) =>
  new Promise((res) => {
    const i = ++id;
    waiting.set(i, res);
    ws.send(JSON.stringify({ id: i, method, params }));
  });
const evalJs = async (expression) => (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result.result.value;
await new Promise((r) => (ws.onopen = r));

await send("Page.enable");
await send("Page.navigate", { url: "http://localhost:3000/" });
await new Promise((r) => setTimeout(r, 5000)); // load and hydrate

const log = await evalJs(`(async () => {
  const ta = document.querySelector('textarea[name=body]');
  ta.value = 'Double click test: wired $3,500, trace 55012.';
  const b = [...document.querySelectorAll('button')].find((x) => /submit|sorting/i.test(x.textContent));
  const out = [];
  const state = (t) => out.push({ afterMs: t, label: b.textContent.trim(), disabled: b.disabled });
  b.click(); await new Promise((r) => setTimeout(r, 80)); state(80);
  b.click(); await new Promise((r) => setTimeout(r, 80)); state(160);
  b.click(); state(160);
  return out;
})()`);
console.log("button state after each click:", JSON.stringify(log));

await new Promise((r) => setTimeout(r, 9000)); // the action runs ~1-3 s, then redirects
console.log("page after submitting:", await evalJs("location.pathname + location.search"));
ws.close();

