const path = require("path");
const root = process.argv[2];
const d = (f) => require(path.join(root, "data", f));
const R = [...d("replies.json"), ...d("heldout-replies.json")];
const L = [...d("labels.json"), ...d("heldout-labels.json")];
for (const id of process.argv[3].split(",")) {
  const r = R.find((x) => x.id === id);
  const l = L.find((x) => x.id === id);
  console.log("#" + id, "[" + r.invoice.number, "$" + r.invoice.amount, "recv", r.received_at + "]", "label:", l.category, l.rank, "->", l.display_category);
  console.log("   body:", JSON.stringify(r.body.slice(0, 150)));
  console.log("   note:", l.note);
}

