python3 - <<'EOF'
def sub(p,pairs):
    s=open(p).read()
    for a,b in pairs:
        assert a in s,(p,a[:70]); s=s.replace(a,b,1)
    open(p,"w").write(s)
sub("src/db/schema.ts",[
 ('export const categoryEnum = pgEnum("category", CATEGORIES);','''// Every review action is one row in `corrections` (POLICY.md section 5, CLAUDE.md "Database").
export const CORRECTION_ACTIONS = ["recategorize", "confirm_paid", "reject_paid", "resolve_offline", "keep"] as const;
export type CorrectionAction = (typeof CORRECTION_ACTIONS)[number];

export const categoryEnum = pgEnum("category", CATEGORIES);'''),
 ('''    finalCategory: categoryEnum("final_category").notNull(),''','''    // v1: the parent + rank after the code rules (internal, never shown). final_category stays the DISPLAYED
    // category, which the promise-horizon rule can set to needs_human without changing parent or rank.
    // Nullable: results from before v1 (prompt v1) never had them.
    finalParent: categoryEnum("final_parent"),
    finalRank: smallint("final_rank"),
    finalCategory: categoryEnum("final_category").notNull(),'''),
 ('''    fromCategory: categoryEnum("from_category"),''','''    // v1: which review action this row records. Existing rows are category changes.
    action: text("action", { enum: CORRECTION_ACTIONS }).notNull().default("recategorize"),
    fromCategory: categoryEnum("from_category"),'''),
])
EOF
npx tsc --noEmit 2>&1 | grep -v "src/db/eval.ts" | head -5; npm run db:generate -- --name v1_review_actions 2>&1 | grep -E "columns|✓|rror"; echo "== generated SQL:"; ls drizzle; cat drizzle/0001_v1_review_actions.sql

