6	import { getDb } from "./client";
7	import { currentResultRows, repliesBySource, type ActiveRun } from "./queries";
8	import { classifications, replies } from "./schema";
9	
10	// The evaluation, built from stored results and MY labels (data/*labels.json). It never reads the
11	// corrections table: a correction made in a demo must not change precision or recall.
12	// Shared by scripts/eval.ts and the /eval page.
13	
14	export type EvalSet = "dataset" | "heldout";
15	
16	// data/labels.json (v1): `display_category` is what is scored; category + rank are the internal parent and rank.
17	type LabelRow = { id: string; display_category: string };
18	const LABEL_FILES: Record<EvalSet, LabelRow[]> = { dataset: datasetLabels, heldout: heldoutLabels };
19	
20	export type EvalResult = {
21	  set: EvalSet;
22	  model: string;
23	  promptVersion: string;
24	  generatedAt: string;
25	  /** Everything spent on this model + prompt version for this set, including failed and retried calls. */
26	  tokens: { prompt: number; completion: number; total: number };
27	  metrics: Metrics;
28	};
29	
30	export async function buildEval(run: ActiveRun, set: EvalSet = "dataset"): Promise<EvalResult> {
31	  const labels = new Map<string, Category>();
32	  for (const l of LABEL_FILES[set]) {
33	    if (!(CATEGORIES as readonly string[]).includes(l.display_category)) throw new Error(`Bad label for ${l.id}: ${l.display_category}`);
34	    labels.set(l.id, l.display_category as Category);
35	  }
36	
37	  const setReplies = await repliesBySource(set);
38	  const bodies = new Map(setReplies.map((r) => [r.id, r.body]));
39	  const current = (await currentResultRows(run)).filter((r) => bodies.has(r.replyId));
40	
41	  const rows: EvalRow[] = current.map((c) => {
42	    const label = labels.get(c.replyId);
43	    if (!label) throw new Error(`No label for reply ${c.replyId}`);
44	    return {
45	      id: c.replyId,
46	      body: bodies.get(c.replyId)!,
47	      label,
48	      // The model alone, before any code rule: its category + rank mapped through POLICY.md section 5 (an invalid pair counts as needs_human).
49	      model: c.modelCategory && c.modelRank !== null ? (displayedCategory(c.modelCategory, c.modelRank) ?? "needs_human") : "needs_human",
50	      final: c.finalCategory,
51	      needsReview: c.needsReview,
52	      reasoning: c.reasoning,
53	      overrideReasons: c.overrideReasons,
54	      reviewReasons: c.reviewReasons,
55	    };
56	  });
