// READ-ONLY preview: the v1 rules replayed over the 120b outputs stored under prompt "v1" (v0 rank meanings).
// No model calls, no database writes. NOT an evaluation: the prompt that produced these is stale.
import { readFileSync } from "node:fs";
import { currentResultRows, repliesBySource, replyToInput } from "/Users/natwshimon/reply-sorter/src/db/queries";
import { policyFromRaw } from "/Users/natwshimon/reply-sorter/src/lib/classifier/classify";
import { ModelOutput } from "/Users/natwshimon/reply-sorter/src/lib/classifier/schema";

const labels = new Map(
  (JSON.parse(readFileSync("/Users/natwshimon/reply-sorter/data/labels.json", "utf8")) as { id: string; category: string; rank: number; display_category: string }[]).map((l) => [l.id, l]),
);
const replies = new Map((await repliesBySource("dataset")).map((r) => [r.id, r]));
const rows = await currentResultRows({ model: "openai/gpt-oss-120b", promptVersion: "v1" });

let agree = 0;
const diffs: string[] = [];
for (const row of rows.sort((a, b) => a.replyId.localeCompare(b.replyId))) {
  const reply = replies.get(row.replyId);
  const label = labels.get(row.replyId);
  if (!reply || !label) continue;
  const raw = ModelOutput.parse(row.rawOutput);
  const p = policyFromRaw(raw, replyToInput(reply));
  if (p.finalCategory === label.display_category) agree++;
  else
    diffs.push(
      `#${row.replyId}  label ${label.category} ${label.rank} -> ${label.display_category} | old-prompt model said ${raw.category} ${raw.rank} (${raw.confidence}) -> v1 rules show ${p.finalCategory}` +
        `${p.overrideReasons.length ? ` [${p.overrideReasons.join(", ")}]` : ""}`,
    );
}
console.log(`New rules over stored OLD-prompt outputs: ${agree}/${rows.length} match the v1 display labels`);
console.log(diffs.join("\n"));

