import { and, eq, inArray } from "/Users/natwshimon/reply-sorter/node_modules/drizzle-orm/index.js";
import { getDb } from "/Users/natwshimon/reply-sorter/src/db/client";
import { classifications, replies } from "/Users/natwshimon/reply-sorter/src/db/schema";

const ids = process.argv[2].split(",");
const model = process.argv[3];
const version = process.argv[4];
const db = getDb();
const rows = await db
  .select({ c: classifications, body: replies.body })
  .from(classifications)
  .innerJoin(replies, eq(replies.id, classifications.replyId))
  .where(and(eq(classifications.model, model), eq(classifications.promptVersion, version), inArray(classifications.replyId, ids)));
for (const { c, body } of rows.sort((a, b) => a.c.replyId.localeCompare(b.c.replyId))) {
  console.log(`#${c.replyId}: model ${c.modelCategory} ${c.modelRank} (${c.confidence}) -> final ${c.finalParent} ${c.finalRank} -> shown ${c.finalCategory} | overrides [${c.overrideReasons}] | needs_review ${c.needsReview}`);
  console.log(`   body: ${JSON.stringify(body.slice(0, 120))}`);
  console.log(`   reasoning: ${c.reasoning}`);
}

